from pathlib import Path
p=Path('work/test_scene_geometry_preparation.cpp')
s=p.read_text()
s=s.replace('#include "scene_geometry_preparation_candidate.h"','#include "scene_geometry_preparation_candidate.h"\n#include "scene_gpu_upload_candidate.h"')
needle='std::cout<<"tick="<<tick'
insert='''std::vector<ModelRenderInputsCandidate> topology;for(auto&instance:geometry){auto&source=asset(instance.model.placement.asset);ModelRenderInputsCandidate input;input.materials.resize(1);for(auto&mesh:source.meshes){if(mesh.model!=0)continue;input.ranges.push_back({uint32_t(input.indices.size()),uint32_t(mesh.triangles.size()*3),0,mesh.body,mesh.model,mesh.mesh});for(auto&triangle:mesh.triangles)for(auto vertex:triangle)input.indices.push_back(vertex);}topology.push_back(std::move(input));}auto upload=prepareSceneGpuUploadCandidate(geometry,topology,[](const auto&v){return double(v.position[2]);});if(upload.vertices.size()!=total||!upload.translucent.empty())throw std::runtime_error("scene upload count");size_t vertexStart=0,indexStart=0;for(size_t m=0;m<geometry.size();++m){for(size_t n=0;n<geometry[m].vertices.size();++n){auto&actual=upload.vertices[vertexStart+n];auto&expected=geometry[m].vertices[n];if(actual.position!=expected.position||actual.normal!=expected.normal||actual.uv!=expected.uv)throw std::runtime_error("scene upload vertex");}for(size_t n=0;n<topology[m].indices.size();++n)if(upload.indices[indexStart+n]!=vertexStart+topology[m].indices[n])throw std::runtime_error("scene upload rebase");vertexStart+=geometry[m].vertices.size();indexStart+=topology[m].indices.size();}for(auto&draw:upload.opaque){auto&r=topology[draw.model].ranges[draw.range];size_t offset=0;for(size_t m=0;m<draw.model;++m)offset+=topology[m].indices.size();if(draw.firstIndex!=offset+r.firstIndex||draw.indexCount!=r.indexCount||draw.materialIndex!=r.materialIndex)throw std::runtime_error("scene upload draw");}std::cout<<"packed_indices="<<upload.indices.size()<<" packed_draws="<<upload.opaque.size()<<" topology_only=1 ";'''
if needle not in s:raise RuntimeError('insertion not found')
s=s.replace(needle,insert+needle)
s=s.replace('scalar_positions_exact=1','gpu_vertex_pack_exact=1 global_indices_exact=1 draw_offsets_exact=1 scalar_positions_exact=1')
p.write_text(s)
